#pragma once
#include <Arduino.h>
#include <type_traits>
// Interface languages of the screens. English is written in the code as t("English"); a language added
// after it comes from src/i18n/I18nTable.h, generated by tools/gen/i18n.py from i18n/firmware/<lang>.json.
// The language number is stored in NVS ("lang"), so the order below never changes; new languages go to
// the end. A stored number this image does not have (upstream Russian and 13 others) falls back to English.
enum Lang:uint8_t {LangEn,LangCount};
extern const char* const langCodes[LangCount]; // "en", ...
extern const char* const langNames[LangCount]; // each in its own language
int langFromCode(const String& code); // -1 when unknown
bool langAvailable(uint8_t l);
uint8_t langStep(uint8_t l,int dir); // the next (dir>0) or previous available language
// The text in the interface language; a string without a translation shows English. tr("English")
// is a macro: the key of the translation (FNV-1a over the English, as tools/gen/i18n.py) is computed
// by the compiler. Strings read from tables go through trText().
constexpr uint32_t i18nFnv(const char* s,uint32_t h){while(*s)h=(h^uint8_t(*s++))*0x01000193u;return h;}
constexpr uint32_t i18nKey(const char* en){return i18nFnv(en,0x811c9dc5u);}
const char* trKey(const char* en,uint32_t key);
inline const char* trText(const char* en){return trKey(en,i18nKey(en));}
#define tr(en) trKey(en,std::integral_constant<uint32_t,i18nKey(en)>::value)
// N_("English"): marks a string of a table for tools/gen/i18n.py; the table is read with trText().
#define N_(en) en
// "5 games": the number and the noun form its language needs. English is the argument
// (number, space, form); translations place the number with {n}.
String plural(unsigned n,const char* one,const char* many);
// The language the site installer chose ("" when the image was not installed from the site).
String installLanguage();

// Drawing text.
// Fonts tried after `font` for a glyph it lacks: Latin-1, then the Latin Extended subset
// (src/i18n/I18nFonts.h). Null-terminated.
const uint8_t* const* fallbackFonts(const uint8_t* font);
bool fontHasGlyph(const uint8_t* font,uint16_t cp);
// Two cells for CJK and other wide glyphs, one otherwise: column counting on the 128x64 screens.
uint8_t glyphCells(uint32_t cp);
uint32_t utf8Next(const String& s,unsigned& i); // the codepoint at i; i moves past it
